// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Proxy c;

    function setUp() public {
        c = new Proxy();
    }

    function _run(address callee, bytes memory data) internal {
        callee = address(this);
        bool reverted;
        try c.forward(callee, data) { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted);
    }

    function testFuzz_run(address callee, bytes memory data) public {
        _run(callee, data);
    }

    fallback() external payable {}

    receive() external payable {}
}
